(function () {
  var mount = document.getElementById("rsf-mount");
  if (!mount) return;
  mount.innerHTML = "<section class=\"rsf-road\" id=\"rsf\" aria-labelledby=\"rsf-title\">\n  <div class=\"rsf-stagewrap\">\n  <div class=\"rsf-stage\">\n    <div class=\"rsf-track\" id=\"rsf-track\">\n      <article class=\"rsf-panel\" data-title=\"Intro\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">Dasa, 2019 to today</p>\n          <h2 id=\"rsf-title\">The Road So Far</h2>\n          <p class=\"rsf-lead\">For more than 7 years I've worked at Dasa, Latin America's largest diagnostic medicine company. I've designed across the patient journey, from scheduling and check-in to e-commerce and home-care operations, across 845+ units and 37 brands.</p>\n          <p class=\"rsf-tags\"><span>Senior Product Designer</span><span>Brazil-based</span><span>Remote-friendly</span><span>Fluent English</span></p>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Canal do Consultor\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2019 · Scheduling tool</p>\n          <h3>Canal do Consultor</h3>\n          <div>\n            <h4 class=\"rsf-k\">Context</h4>\n            <p class=\"rsf-ctx\">Dasa scheduled exams on a third-party system with significant costs. I created Canal do Consultor (Consultant Channel), Dasa's own exam scheduling tool, to replace it.</p>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">Results</h4>\n            <div class=\"rsf-results\">\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">20M+</p><p class=\"rsf-result-text\">exams handled by the scheduling system Dasa owns</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">2023</p><p class=\"rsf-result-text\">the year Dasa stopped depending on the third-party scheduling system</p></div>\n            </div>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">My role</h4>\n            <p class=\"rsf-role\">Designed the tool from the start. It was my first product at Dasa.</p>\n          </div>\n          <p class=\"rsf-case-soon\">Case study in progress</p>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"COVID-19 Microsite\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2020 · Scheduling</p>\n          <h3>COVID-19 Microsite</h3>\n          <div>\n            <h4 class=\"rsf-k\">Context</h4>\n            <p class=\"rsf-ctx\">Patients could only book COVID-19 exams by phone, and the contact center was overwhelmed. Dasa needed a self-service way to find the right exam and book it online, across brands with no digital scheduling.</p>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">Results</h4>\n            <div class=\"rsf-results\">\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">−28%</p><p class=\"rsf-result-text\">contact-center calls about exam scheduling</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">5 weeks</p><p class=\"rsf-result-text\">from briefing to handoff</p></div>\n            </div>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">My role</h4>\n            <p class=\"rsf-role\">Only designer on the project: research with contact-center teams, information architecture, prototyping, validation and handoff.</p>\n          </div>\n          <p class=\"rsf-case-soon rsf-case-soon--next\">Case study in the next section <span aria-hidden=\"true\">↓</span></p>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Vaccine E-commerce\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2021 · Patient-facing</p>\n          <h3>Vaccine E-commerce</h3>\n          <div>\n            <h4 class=\"rsf-k\">Context</h4>\n            <p class=\"rsf-ctx\">The vaccine store had a long checkout and looked nothing like the lab sites that sent people to it, so users left before buying. The goal: cut drop-off, lift conversion and add home-care scheduling, on top of Dasa's design system.</p>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">Results</h4>\n            <div class=\"rsf-results\">\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">+22%</p><p class=\"rsf-result-text\">conversion rate</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">−24%</p><p class=\"rsf-result-text\">checkout abandonment</p></div>\n            </div>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">My role</h4>\n            <p class=\"rsf-role\">Led discovery and redesign: 1.5 years of analytics, research, information architecture, usability tests and handoff on ALMA, Dasa's design system.</p>\n          </div>\n          <p class=\"rsf-case-soon rsf-case-soon--next\">Case study in the next section <span aria-hidden=\"true\">↓</span></p>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Lab Check-in\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2022–2025 · Phygital</p>\n          <h3>Lab Check-in</h3>\n          <div>\n            <h4 class=\"rsf-k\">Context</h4>\n            <p class=\"rsf-ctx\">Patients took a ticket and waited to be called (T1), then spent time at the reception desk before the exam waiting room (T2). Check-in is a phygital flow across the patient's phone and the lab unit, and a major strategic bet. I was the designer responsible from 2022 to mid-2025, through its full redesign.</p>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">Results</h4>\n            <div class=\"rsf-results rsf-results--3\">\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">22 → 4</p><p class=\"rsf-result-text\">flows after the redesign, each with a clear value proposition</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">T2 = 0</p><p class=\"rsf-result-text\">airline-style check-in at the unit: no stop at reception for part of the patients</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">−30 s</p><p class=\"rsf-result-text\">average desk time per visit, cut over 12 months of shipping features</p></div>\n            </div>\n          </div>\n          <p class=\"rsf-case-soon\">Case study in progress</p>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Unit Docs and Gliese\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2022–2025<span class=\"rsf-pill\">Alongside check-in</span></p>\n          <section class=\"rsf-entry\" data-stop=\"5\">\n            <h3>Unit Docs</h3>\n            <p class=\"rsf-ctx\">Dasa's paperless initiative: digitizing every form, for patients and for reporting physicians, the doctors who write the patients' reports.</p>\n            <p class=\"rsf-role\">I aligned questionnaires across teams to cut repeated questions, reinforcing Dasa's brand pillar of patient welcome.</p>\n          </section>\n          <section class=\"rsf-entry\" data-stop=\"6\">\n            <h3>Gliese</h3>\n            <p class=\"rsf-ctx\">Dasa's internal patient service system, a legacy product from around 2002, where staff open patient records and issue result protocols.</p>\n            <p class=\"rsf-role\">Structural changes weren't possible, so I reworked information hierarchy to shorten service time, alongside check-in until a dedicated designer joined.</p>\n          </section>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Tracking\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">2022–2025<span class=\"rsf-pill\">Alongside check-in</span></p>\n          <section class=\"rsf-entry\" data-stop=\"7\">\n            <h3>Tracking</h3>\n            <p class=\"rsf-ctx\">Tracks the patient inside the unit to help navigation and measure time. Its interfaces are totems, TVs, signs and floor strips: wayfinding.</p>\n            <p class=\"rsf-role\">I partnered with the Tracking team: the unit totem is check-in's logical continuation, the first guidance a patient gets on arrival, so we stayed in constant alignment. A main goal is less human help to direct patients: it gives a digital path to people who prefer to have no human interaction on their way to sample collection.</p>\n          </section>\n        </div>\n      </article>\n      <article class=\"rsf-panel\" data-title=\"Home-Care Mobile App\">\n        <div class=\"rsf-inner\">\n          <p class=\"rsf-label\">Now · Mobile</p>\n          <h3>Home-Care Mobile App</h3>\n          <div>\n            <h4 class=\"rsf-k\">Context</h4>\n            <p class=\"rsf-ctx\">Home-care professionals collect samples at patients' homes and need a tool that works mid-visit. I design the mobile product for home-collection operations.</p>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">Results</h4>\n            <div class=\"rsf-results\">\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">2×</p><p class=\"rsf-result-text\">home-care revenue, as digital helped expand the service across Brazil</p></div>\n              <div class=\"rsf-result\"><p class=\"rsf-result-value\">14 states</p><p class=\"rsf-result-text\">where home-care professionals work with the app</p></div>\n            </div>\n          </div>\n          <div>\n            <h4 class=\"rsf-k\">My role</h4>\n            <p class=\"rsf-role\">Designer responsible for home care: I design the product and support the team's designers.</p>\n          </div>\n          <p class=\"rsf-case-soon\">Case study in progress</p>\n        </div>\n      </article>\n    </div>\n  </div>\n  <div class=\"rsf-ctrls\">\n    <button type=\"button\" class=\"rsf-arrow-btn rsf-arrow-btn--prev\" id=\"prev\" aria-label=\"Previous\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M15 5l-7 7 7 7\"/></svg></button>\n    <button type=\"button\" class=\"rsf-arrow-btn rsf-arrow-btn--next rsf-is-hint\" id=\"next\" aria-label=\"Next\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M9 5l7 7-7 7\"/></svg></button>\n  </div>\n  </div>\n  <nav class=\"rsf-tl\" aria-label=\"Product timeline\">\n    <div class=\"rsf-tl-inner\">\n      <div class=\"rsf-tl-line\" aria-hidden=\"true\"><span class=\"rsf-tl-base\"></span><span class=\"rsf-tl-fill\"></span></div>\n      <div class=\"rsf-tl-pins\">\n        <button type=\"button\" class=\"rsf-tl-pin\" data-target=\"1\" style=\"--f:0\" aria-label=\"2019: Canal do Consultor\"></button>\n        <button type=\"button\" class=\"rsf-tl-pin\" data-target=\"2\" style=\"--f:2\" aria-label=\"2020 and 2021: COVID-19 Microsite and Vaccine E-commerce\"></button>\n        <button type=\"button\" class=\"rsf-tl-pin\" data-target=\"4\" style=\"--f:4\" aria-label=\"2022 to 2025: Lab Check-in, Unit Docs and Gliese\"></button>\n        <button type=\"button\" class=\"rsf-tl-pin\" data-target=\"7\" style=\"--f:6\" aria-label=\"Now: Tracking and Home-Care Mobile App\"></button>\n      </div>\n      <ol class=\"rsf-tl-list\">\n        <li data-panel=\"1\"><span class=\"rsf-tl-year\">2019</span><span class=\"rsf-tl-name\">Canal do Consultor</span></li>\n        <li data-panel=\"2\"><span class=\"rsf-tl-year\">2020</span><span class=\"rsf-tl-name\">COVID-19 Microsite</span></li>\n        <li data-panel=\"3\"><span class=\"rsf-tl-year\">2021</span><span class=\"rsf-tl-name\">Vaccine E-commerce</span></li>\n        <li data-panel=\"4\"><span class=\"rsf-tl-year\">2022</span><span class=\"rsf-tl-name\">Lab Check-in</span></li>\n        <li class=\"rsf-is-also\" data-panel=\"5\"><span class=\"rsf-tl-year\">2022–25</span><span class=\"rsf-tl-name\">Unit Docs + Gliese</span></li>\n        <li class=\"rsf-is-also\" data-panel=\"6\"><span class=\"rsf-tl-year\">2022–25</span><span class=\"rsf-tl-name\">Tracking</span></li>\n        <li data-panel=\"7\"><span class=\"rsf-tl-year\">Now</span><span class=\"rsf-tl-name\">Home-Care Mobile App</span></li>\n        <li class=\"rsf-tl-tag\" aria-hidden=\"true\" style=\"grid-column: 5 / 7\"><span class=\"rsf-pill\">Alongside check-in</span></li>\n      </ol>\n    </div>\n  </nav>\n  <p class=\"rsf-sr-only\" id=\"rsf-live\" aria-live=\"polite\"></p>\n</section>";
(function () {
  var road = document.getElementById('rsf');
  var track = document.getElementById('rsf-track');
  var panels = Array.prototype.slice.call(track.children);
  var items = Array.prototype.slice.call(document.querySelectorAll('.rsf-tl-list li:not(.rsf-tl-tag)'));
  var stops = items.map(function (li) { return { el: li, panel: parseInt(li.getAttribute('data-panel'), 10) }; });
  var pins = Array.prototype.slice.call(document.querySelectorAll('.rsf-tl-pin')).map(function (b) {
    return { btn: b, panel: parseInt(b.getAttribute('data-target'), 10), f: parseFloat(b.style.getPropertyValue('--f')) };
  });
  var live = document.getElementById('rsf-live');
  var prevBtn = document.getElementById('prev');
  var nextBtn = document.getElementById('next');
  var stage = document.querySelector('.rsf-stage');
  var tl = document.querySelector('.rsf-tl');
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)');
  var N = stops.length;
  var mq = window.matchMedia('(max-width: 720px)');
  var pos = 0; // first visible panel (0 = intro)

  road.style.setProperty('--n', N);
  road.style.setProperty('--panels', panels.length);

  // A timeline stop points to a panel. A panel can hold more than one product (the Alongside blocks),
  // so several stops can share a panel, and all of them are active while that panel is on screen.
  // Desktop shows two panels and moves two at a time. Mobile shows one panel and moves one at a time.
  function snap(i) {
    return mq.matches ? i : Math.min(Math.floor(i / 2) * 2, panels.length - 2);
  }
  function visible(i) { return mq.matches ? i === pos : (i === pos || i === pos + 1); }

  function fit() {
    // One fixed height for every page (the tallest panel), so the section never jumps between pages.
    var h = 0;
    panels.forEach(function (p) { h = Math.max(h, p.offsetHeight); });
    if (h) stage.style.minHeight = h + 'px';
  }

  // Slow, eased horizontal glide (native 'smooth' is too quick). Any manual interaction cancels it.
  var glideId = 0;
  function glide(to, dur) {
    window.cancelAnimationFrame(glideId);
    var from = tl.scrollLeft, dist = to - from;
    if (!dur || Math.abs(dist) < 2) { tl.scrollLeft = to; return; }
    var t0 = null;
    function step(t) {
      if (t0 === null) t0 = t;
      var k = Math.min(1, (t - t0) / dur);
      var e = k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2;
      tl.scrollLeft = from + dist * e;
      if (k < 1) glideId = window.requestAnimationFrame(step);
    }
    glideId = window.requestAnimationFrame(step);
  }
  ['wheel', 'touchstart'].forEach(function (n) {
    tl.addEventListener(n, function () { window.cancelAnimationFrame(glideId); }, { passive: true });
  });

  // Keep the active stops centred in the scrolling timeline, so nobody has to scroll it by hand.
  function followTimeline(smooth) {
    if (tl.scrollWidth <= tl.clientWidth + 1) return;
    var left = Infinity, right = -Infinity, base = tl.getBoundingClientRect().left;
    stops.forEach(function (s) {
      if (!visible(s.panel)) return;
      var r = s.el.getBoundingClientRect();
      left = Math.min(left, r.left - base + tl.scrollLeft);
      right = Math.max(right, r.right - base + tl.scrollLeft);
    });
    if (left === Infinity) { left = 0; right = 0; }
    var target = (left + right) / 2 - tl.clientWidth / 2;
    target = Math.max(0, Math.min(tl.scrollWidth - tl.clientWidth, target));
    glide(target, smooth && !reduce.matches ? 1100 : 0);
  }

  function update(announce) {
    var fv = 0;
    road.style.setProperty('--pos', pos);
    var names = [];
    panels.forEach(function (p, i) {
      var show = visible(i);
      p.inert = !show;
      p.setAttribute('aria-hidden', show ? 'false' : 'true');
      if (show) names.push(p.getAttribute('data-title'));
    });
    stops.forEach(function (s, k) {
      var on = visible(s.panel);
      s.el.classList.toggle('rsf-is-active', on);
      if (on) fv = Math.max(fv, k);
    });
    pins.forEach(function (pn) {
      var on = visible(pn.panel);
      pn.btn.classList.toggle('rsf-is-active', on);
      pn.btn.classList.toggle('rsf-is-past', !on && pn.panel < pos);
      if (on) { pn.btn.setAttribute('aria-current', 'step'); fv = pn.f; }
      else pn.btn.removeAttribute('aria-current');
    });
    road.style.setProperty('--fv', fv);
    prevBtn.disabled = pos <= 0;
    nextBtn.disabled = pos >= (mq.matches ? panels.length - 1 : panels.length - 2);
    fit();
    followTimeline(announce);
    if (announce) live.textContent = 'Showing ' + names.join(' and ');
  }

  function focusPin() {
    var t = pins[0];
    pins.forEach(function (pn) { if (visible(pn.panel) || pn.panel < pos) t = pn; });
    t.btn.focus();
  }

  function goPanel(i, stop, fromKeyboard) {
    i = Math.max(0, Math.min(panels.length - 1, i));
    var newPos = snap(i);
    if (newPos !== pos) {
      var hops = Math.abs(newPos - pos) / (mq.matches ? 1 : 2);
      road.style.setProperty('--dur', Math.min(1100, 650 + (hops - 1) * 120) + 'ms');
    }
    pos = newPos;
    nextBtn.classList.remove('rsf-is-hint');
    update(true);
    if (fromKeyboard) focusPin();
  }

  function stepBy(dir) { goPanel(pos + dir * (mq.matches ? 1 : 2)); }
  prevBtn.addEventListener('click', function () { stepBy(-1); });
  nextBtn.addEventListener('click', function () { stepBy(1); });

  pins.forEach(function (pn) {
    pn.btn.addEventListener('click', function () { goPanel(pn.panel); });
  });

  // Arrow keys on the timeline move one page: two panels on desktop, one on mobile.
  tl.addEventListener('keydown', function (e) {
    var step = mq.matches ? 1 : 2, target = null;
    if (e.key === 'ArrowRight') target = pos + step;
    else if (e.key === 'ArrowLeft') target = pos - step;
    else if (e.key === 'Home') target = 0;
    else if (e.key === 'End') target = panels.length - 1;
    else return;
    e.preventDefault();
    if (target < 0 || target > panels.length - 1) return;
    goPanel(target, null, true);
  });

  // Swipe on mobile: one panel per swipe. Vertical scrolling stays with the browser (touch-action: pan-y).
  var sx = null, sy = 0;
  stage.addEventListener('touchstart', function (e) {
    if (!mq.matches || e.touches.length !== 1) { sx = null; return; }
    sx = e.touches[0].clientX; sy = e.touches[0].clientY;
  }, { passive: true });
  stage.addEventListener('touchend', function (e) {
    if (sx === null) return;
    var t = e.changedTouches[0], dx = t.clientX - sx, dy = t.clientY - sy;
    sx = null;
    if (Math.abs(dx) > 48 && Math.abs(dx) > Math.abs(dy) * 1.4) goPanel(pos + (dx < 0 ? 1 : -1));
  }, { passive: true });

  // Mouse drag on desktop: same gesture as the swipe (touch keeps its own handler above).
  var dx0 = null, dy0 = 0, dragged = false, pid = null;
  stage.addEventListener('pointerdown', function (e) {
    if (e.pointerType !== 'mouse' || e.button !== 0) return;
    dx0 = e.clientX; dy0 = e.clientY; dragged = false; pid = e.pointerId;
  });
  stage.addEventListener('pointermove', function (e) {
    if (dx0 === null || e.pointerId !== pid) return;
    if (!dragged && Math.abs(e.clientX - dx0) > 6) {
      dragged = true;
      stage.classList.add('rsf-is-dragging');
      try { stage.setPointerCapture(pid); } catch (err) {}
    }
  });
  function endDrag(e, cancel) {
    if (dx0 === null || e.pointerId !== pid) return;
    var dx = e.clientX - dx0, dy = e.clientY - dy0;
    dx0 = null;
    stage.classList.remove('rsf-is-dragging');
    try { stage.releasePointerCapture(pid); } catch (err) {}
    if (!cancel && dragged && Math.abs(dx) > 60 && Math.abs(dx) > Math.abs(dy) * 1.2) {
      goPanel(pos + (dx < 0 ? 1 : -1) * (mq.matches ? 1 : 2));
    }
  }
  stage.addEventListener('pointerup', function (e) { endDrag(e, false); });
  stage.addEventListener('pointercancel', function (e) { endDrag(e, true); });
  // Mouse drag on the timeline: pan it when it overflows, otherwise change page like the stage.
  var tx0 = null, ts0 = 0, tdrag = false, tpid = null, tPan = false;
  tl.addEventListener('pointerdown', function (e) {
    if (e.pointerType !== 'mouse' || e.button !== 0) return;
    tx0 = e.clientX; ts0 = tl.scrollLeft; tdrag = false; tpid = e.pointerId;
    tPan = tl.scrollWidth > tl.clientWidth + 1;
    window.cancelAnimationFrame(glideId);
  });
  tl.addEventListener('pointermove', function (e) {
    if (tx0 === null || e.pointerId !== tpid) return;
    if (!tdrag && Math.abs(e.clientX - tx0) > 6) {
      tdrag = true; tl.classList.add('rsf-is-dragging');
      try { tl.setPointerCapture(tpid); } catch (err) {}
    }
    if (tdrag && tPan) tl.scrollLeft = ts0 - (e.clientX - tx0);
  });
  function endTl(e, cancel) {
    if (tx0 === null || e.pointerId !== tpid) return;
    var dx = e.clientX - tx0;
    tx0 = null; tl.classList.remove('rsf-is-dragging');
    try { tl.releasePointerCapture(tpid); } catch (err) {}
    if (!cancel && tdrag && !tPan && Math.abs(dx) > 60) goPanel(pos + (dx < 0 ? 1 : -1) * (mq.matches ? 1 : 2));
  }
  tl.addEventListener('pointerup', function (e) { endTl(e, false); });
  tl.addEventListener('pointercancel', function (e) { endTl(e, true); });
  tl.addEventListener('click', function (e) { if (tdrag) { e.preventDefault(); e.stopPropagation(); tdrag = false; } }, true);
  tl.addEventListener('dragstart', function (e) { e.preventDefault(); });

  // A drag that ends over a link must not open it.
  stage.addEventListener('click', function (e) { if (dragged) { e.preventDefault(); e.stopPropagation(); dragged = false; } }, true);
  stage.addEventListener('dragstart', function (e) { e.preventDefault(); });

  Array.prototype.forEach.call(document.querySelectorAll('[data-proto]'), function (a) {
    a.addEventListener('click', function (e) { e.preventDefault(); });
  });

  function onMq() { pos = snap(pos); update(false); }
  if (mq.addEventListener) mq.addEventListener('change', onMq);
  window.addEventListener('resize', function () { fit(); followTimeline(false); });
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);
  onMq();
  window.requestAnimationFrame(function () { stage.classList.add('rsf-is-ready'); });
})();
})();
